"use strict";(self["webpackChunkmolmash"]=self["webpackChunkmolmash"]||[]).push([[2073],{2073:function(a,e,t){t.r(e),t.d(e,{default:function(){return k}});var r=t(641),l=t(953),o=t(971);const s={class:"solutions-content__text"};var d=(0,r.pM)({__name:"index",setup(a){return(a,e)=>((0,r.uX)(),(0,r.CE)("article",s,[(0,r.bF)((0,l.R1)(o.E),{tagName:"p",size:"l",color:"dark-gray2"},{default:(0,r.k6)((()=>[(0,r.eW)(" Сгущенное с сахаром молоко - концентрированный или сгущенный молочный продукт с сахаром, массовая доля белка в сухих обезжиренных веществах молока составляет не менее чем 34 процента. Для производства сгущенного с сахаром молока применяют различные комплексы оборудования, составляющие технологические линии. Состав оборудования в этих линиях зависит от состава и качества сырья и его вида, который определяет его механическую и тепловую обработку. ")])),_:1}),(0,r.bF)((0,l.R1)(o.E),{tagName:"p",size:"l",color:"dark-gray2"},{default:(0,r.k6)((()=>[(0,r.eW)(" В линии, которую реализует ООО «Завод Молмаш», основным сырьём являются сухое обезжиренное молоко, жиры животного или растительного происхождения.Вспомогательными компонентами являются сахарный песок, вода и лактоза. В качестве жиров животного или растительного происхождения применяют жировые системы, имеющие с молочным жиром аналогичный жирнокислотный состав, физико-химические и структурно-механические свойства. Увеличенное содержания в таких жировых системах полиненасыщенных жирных кислот, а также отсутствие холестерина увеличивает пищевую ценность продукта. ")])),_:1}),(0,r.bF)((0,l.R1)(o.E),{tagName:"p",size:"l",color:"dark-gray2"},{default:(0,r.k6)((()=>[(0,r.eW)(" Основными технологическими операциями производства сгущенного с сахаром молока являются подготовка сырья и вспомогательных компонентов, составление смеси продукта, её нормализация, пастеризация, охлаждение и фасование. ")])),_:1}),(0,r.bF)((0,l.R1)(o.E),{tagName:"p",size:"l",color:"dark-first"},{default:(0,r.k6)((()=>[(0,r.eW)(" Описание работы линии ")])),_:1}),(0,r.bF)((0,l.R1)(o.E),{tagName:"p",size:"l",color:"dark-gray2"},{default:(0,r.k6)((()=>[(0,r.eW)(' Схема линии производства сгущенного с сахаром молока ООО «Заводом Молмаш» приведена ниже. Оборудование для приёма сырья и вспомогательных компонентов на схеме не показано. Подготовка сырья и вспомогательных компонентов заключается в следующем. Жиры животного или растительного происхождения разогревают в установке закрытого типа для расплавления жира П8-ОЖТ-1000. Для повышения степени дисперсности жировой эмульсии ее обрабатывают агрегате П8-ОРД-10М с воронкой роторного типа с многократной циркуляцией жировой эмульсии через него в течение времени, достаточного для получения однородной дисперсии без видимого свободного жира на поверхности. При механической обработке в агрегате температура жировой эмульсии должна составлять 45±5 оС. Повышение температуры жировой эмульсии может привести к снижению ее стабильности и выделению свободного жидкого жира. Для составления смеси продукта и её нормализации рассчитанную массу сухого обезжиренного молоко восстанавливают путём его растворения в воде при температуре 45±5 оС в агрегате диспергирующим. Восстановленное сухое обезжиренное молоко из агрегата диспергирующего роторного подают в технологическую ёмкость П8-БМШ-М-1000. Восстановленное сухое обезжиренное молоко охлаждают до температуры 5-8 °С и выдерживают при этой температуре 2-3 часа с целью набухания белков, устранения "водяного" привкуса, улучшения консистенции восстановленного молока. Требуемое количество сахара вносится в твердом виде. Необходимое количество воды и предварительно растопленного до консистенции сметаны жира отмеривают соответственно счётчиком-расходомером для воды и счётчиком-расходомером для жира и вносят в технологическую емкость П8-БМШ-М-1000. Предварительно растопленный жир перекачивают в технологическую емкость насосом ОНЦ 6,3/20К5-1,5/2. Смесь продукта тщательно вымешивают. В итоге получают смесь, соответствующую по массовой доле сухих веществ, влаги и жиру - готовому продукту. Пастеризацию нормализованной смеси продукта производят в технологической емкости при температуре 90-95 °С. Затем пастеризованную нормализованную смесь продукта охлаждают в этой же технологической емкости. При охлаждении пастеризованную нормализованную смесь продукта вымешивают мешалками технологической емкости П8-БМШ-М-1000 и вносят затравку (лактозу 0,02 %) для образования центров кристаллизации и кристаллизации лактозы. ')])),_:1}),(0,r.bF)((0,l.R1)(o.E),{tagName:"p",size:"l",color:"dark-gray2"},{default:(0,r.k6)((()=>[(0,r.eW)(" Для получения высококачественной однородной смеси продукта её гомогенизируют. Из технологической ёмкости смесь продукта шестерённым насосом ШНК-15-2 подают в гомогенизатор ГМ-1,0/20М2Д. Гомогенизированный продукт поступает в технологическую ёмкость П8-БМШ-М-1000 или его перекачивают шестерённым насосом ШНК-15-2 в автомат розлива. ")])),_:1}),(0,r.bF)((0,l.R1)(o.E),{tagName:"p",size:"l",color:"dark-gray2"},{default:(0,r.k6)((()=>[(0,r.eW)(" Технологическая емкость П8-БМШ-М-1000 между гомогенизатором ГМ-1,0/20М2Д и автоматом для розлива обеспечивает сглаживание неравномерностей в работе последнего. Кроме того, технологическая емкость П8-БМШ-М-1000 обеспечивает промежуточное хранение продукта в технологической линии с последующим розливом его в тару, а при вынужденных остановках играет роль накопителя продукта. ")])),_:1})]))}}),u=t(6262);const c=(0,u.A)(d,[["__scopeId","data-v-0957dbe7"]]);var k=c}}]);
